CREATE OR REPLACE PROCEDURE sp(para_Player_id integer, para_Player_name text, para_Rank integer, para_Gender text, para_Votes_bonus integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_player_exists boolean;
    v_coach_rank_exists boolean;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM "player"
        WHERE "Player_ID" = para_Player_id
    ) INTO v_player_exists;

    IF v_player_exists THEN
        CALL sp_part1(para_Votes_bonus, para_Player_name, para_Rank, para_Gender);
        CALL sp_part2(para_Player_id, 5);
        UPDATE "player"
        SET "Sponsor_name" = 'orchestrated_update'
        WHERE "Player_ID" = para_Player_id;
    ELSE
        INSERT INTO "player" ("Player_ID", "Player_name", "Votes", "Rank")
        VALUES (para_Player_id, para_Player_name, 0, para_Rank);
        CALL sp_part2(para_Player_id, para_Votes_bonus);
        UPDATE "coach"
        SET "Rank" = "Rank" + para_Votes_bonus
        WHERE "Coach_ID" = 1;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM "coach"
        WHERE "Rank" = para_Rank
    ) INTO v_coach_rank_exists;

    IF v_coach_rank_exists THEN
        CALL sp_part1(10, para_Player_name, para_Rank, para_Gender);
    ELSE
        UPDATE "player"
        SET "Votes" = "Votes" + para_Votes_bonus
        WHERE "Player_ID" = para_Player_id;
    END IF;

    UPDATE "player"
    SET "Sponsor_name" = 'orchestrated_update',
        "Votes" = "Votes" + para_Votes_bonus
    WHERE "Player_ID" = para_Player_id
      AND "Sponsor_name" IS DISTINCT FROM 'orchestrated_update';

    UPDATE "player"
    SET "Occupation" = CASE
            WHEN "Votes" > para_Votes_bonus * 2 THEN 'orchestrated_update'
            ELSE 'orchestrated_pending'
        END
    WHERE "Player_ID" = para_Player_id;
END;
$$;

